package com.gameaggregator.incidentservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="incident_timeline") public class IncidentTimeline{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID incidentId;@Column(nullable=false)public UUID actorId;@Column(nullable=false)public String type;@Lob @Column(nullable=false)public String message;@Column(nullable=false)public Instant createdAt=Instant.now();protected IncidentTimeline(){}public IncidentTimeline(UUID i,UUID a,String t,String m){incidentId=i;actorId=a;type=t;message=m;}}